--
-- Table structure for table `tbl_plan_purchase`
--

CREATE TABLE `tbl_plan_purchase` (
  `id` int NOT NULL,
  `plan_id` int NOT NULL,
  `parent_id` int NOT NULL,
  `student_id` int NOT NULL,
